# ---------------------------------------------------------------------------
# TMDb HTTP client: Bearer only; credentials are never placed in URLs/errors.
# ---------------------------------------------------------------------------
Path("windows-installer/src/tmdb_client.py").write_text('''from __future__ import annotations\n\nimport json\nfrom typing import Any, Callable, Mapping\nfrom urllib.error import HTTPError, URLError\nfrom urllib.parse import urlencode\nfrom urllib.request import Request, urlopen\n\nTMDB_API_BASE = "https://api.themoviedb.org/3"\n_CREDENTIAL_QUERY_NAMES = {"api_key", "access_token", "token", "authorization"}\n\n\nclass TmdbError(RuntimeError):\n    pass\n\n\nclass TmdbClient:\n    def __init__(\n        self,\n        access_token: str,\n        *,\n        opener: Callable[..., Any] = urlopen,\n        timeout: float = 15.0,\n    ) -> None:\n        token = str(access_token or "").strip()\n        if not token:\n            raise ValueError("TMDb API Read Access Token is required")\n        self._access_token = token\n        self._opener = opener\n        self._timeout = timeout\n\n    def get_json(self, path: str, params: Mapping[str, Any] | None = None) -> Any:\n        endpoint = str(path or "").strip()\n        if not endpoint.startswith("/") or endpoint.startswith("//"):\n            raise ValueError("TMDb path must be an API-relative path")\n        query = dict(params or {})\n        if any(str(key).lower() in _CREDENTIAL_QUERY_NAMES for key in query):\n            raise ValueError("credentials must not be placed in TMDb query parameters")\n        encoded = urlencode([(str(k), str(v)) for k, v in query.items() if v is not None])\n        url = TMDB_API_BASE + endpoint + ("?" + encoded if encoded else "")\n        request = Request(\n            url,\n            headers={\n                "Authorization": f"Bearer {self._access_token}",\n                "Accept": "application/json",\n            },\n            method="GET",\n        )\n        try:\n            response = self._opener(request, timeout=self._timeout)\n            try:\n                body = response.read()\n            finally:\n                close = getattr(response, "close", None)\n                if callable(close):\n                    close()\n        except HTTPError as exc:\n            raise TmdbError(f"TMDb API returned HTTP {exc.code}") from None\n        except (URLError, TimeoutError, OSError):\n            raise TmdbError("TMDb API connection failed") from None\n        try:\n            return json.loads(body.decode("utf-8"))\n        except (UnicodeDecodeError, json.JSONDecodeError):\n            raise TmdbError("TMDb API returned invalid JSON") from None\n\n    def configuration(self) -> dict[str, Any]:\n        value = self.get_json("/configuration")\n        return value if isinstance(value, dict) else {}\n\n    def search_movie(self, query: str, *, year: str | int | None = None, language: str = "ja-JP") -> dict[str, Any]:\n        params: dict[str, Any] = {"query": query, "language": language, "include_adult": "false"}\n        if year not in (None, ""):\n            params["year"] = year\n        value = self.get_json("/search/movie", params)\n        return value if isinstance(value, dict) else {}\n\n    def search_tv(self, query: str, *, first_air_date_year: str | int | None = None, language: str = "ja-JP") -> dict[str, Any]:\n        params: dict[str, Any] = {"query": query, "language": language, "include_adult": "false"}\n        if first_air_date_year not in (None, ""):\n            params["first_air_date_year"] = first_air_date_year\n        value = self.get_json("/search/tv", params)\n        return value if isinstance(value, dict) else {}\n''', encoding="utf-8")

# ---------------------------------------------------------------------------
# Generic cache helper backed by tmdb_api_cache.
# ---------------------------------------------------------------------------
Path("windows-installer/src/tmdb_cache.py").write_text('''from __future__ import annotations\n\nimport json\nimport sqlite3\nfrom datetime import datetime\nfrom typing import Any\n\nfrom database import now_iso\n\n\ndef get_cached_json(connection: sqlite3.Connection, cache_key: str, *, now: str | None = None) -> Any | None:\n    row = connection.execute(\n        "SELECT payload_json, expires_at FROM tmdb_api_cache WHERE cache_key=?",\n        (str(cache_key),),\n    ).fetchone()\n    if row is None:\n        return None\n    expires_at = row["expires_at"]\n    if expires_at:\n        current = datetime.fromisoformat(now or now_iso())\n        expiry = datetime.fromisoformat(str(expires_at))\n        if expiry <= current:\n            return None\n    return json.loads(str(row["payload_json"]))\n\n\ndef put_cached_json(\n    connection: sqlite3.Connection,\n    cache_key: str,\n    payload: Any,\n    *,\n    fetched_at: str | None = None,\n    expires_at: str | None = None,\n) -> None:\n    connection.execute(\n        """\n        INSERT INTO tmdb_api_cache(cache_key, payload_json, fetched_at, expires_at)\n        VALUES (?, ?, ?, ?)\n        ON CONFLICT(cache_key) DO UPDATE SET\n            payload_json=excluded.payload_json,\n            fetched_at=excluded.fetched_at,\n            expires_at=excluded.expires_at\n        """,\n        (str(cache_key), json.dumps(payload, ensure_ascii=False, separators=(",", ":")), fetched_at or now_iso(), expires_at),\n    )\n\n\ndef delete_cached_json(connection: sqlite3.Connection, cache_key: str) -> None:\n    connection.execute("DELETE FROM tmdb_api_cache WHERE cache_key=?", (str(cache_key),))\n''', encoding="utf-8")

